@Test
@SuppressWarnings("ThrowableResultIgnored")
public void testSelectAppropriateHandler() throws URISyntaxException, InterruptedException, ExecutionException {
    Future<Object> x0 = new Intent("NONE", new URI("unsupported://resource")).execute();
    Exception e = null;
    try {
        x0.get();
    } catch (InterruptedException | ExecutionException ex) {
        e = ex;
    }
    assertTrue(e instanceof ExecutionException && (e.getCause() instanceof NoAvailableHandlerException));
    Future<Object> x1 = new Intent("NONE", new URI("broken://resource")).execute();
    try {
        x1.get();
    } catch (InterruptedException | ExecutionException ex) {
        e = ex;
    }
    assertTrue(e instanceof ExecutionException);
    Future<Object> x2 = new Intent("NONE", new URI("brokensb://resource")).execute();
    try {
        x2.get();
    } catch (InterruptedException | ExecutionException ex) {
        e = ex;
    }
    assertTrue(e instanceof ExecutionException);
    Future<Object> f0 = new Intent("TEST", new URI("unsupported://resource")).execute();
    assertEquals(HANDLED_BY_TEST, f0.get());
    Future<Object> f1 = new Intent(Intent.ACTION_VIEW, new URI("netbeans://resource")).execute();
    assertEquals(HANDLED_BY_NB, f1.get());
    Future<Object> f2 = new Intent(Intent.ACTION_VIEW, new URI("netbeans://resource?someParam=x")).execute();
    assertEquals(HANDLED_BY_NB, f2.get());
    Future<Object> f3 = new Intent(Intent.ACTION_VIEW, new URI("netbeans://resource?x=y&requiredParam=123")).execute();
    assertEquals(HANDLED_BY_NB_PARAM, f3.get());
    Future<Object> f4 = new Intent(Intent.ACTION_VIEW, new URI("setback://resource")).execute();
    assertEquals(HANDLED_BY_SETBACK, f4.get());
}

@Test
public void testExecutionWithCallback() throws URISyntaxException, InterruptedException, ExecutionException {
    class CheckingCallback implements Callback {

        private final Semaphore s = new Semaphore(0);

        private Exception lastException = null;

        private Object lastResult = null;

        @Override
        public void success(Object result) {
            lastException = null;
            lastResult = result;
            s.release();
        }

        @Override
        public void failure(Exception exception) {
            lastException = exception;
            lastResult = null;
            s.release();
        }

        public void checkLastResult(Object expectedResult) {
            try {
                s.acquire();
            } catch (InterruptedException ex) {
                Exceptions.printStackTrace(ex);
            }
            assertEquals(expectedResult, lastResult);
        }

        public void checkLastFailure(Class<? extends Exception> ec) {
            try {
                s.acquire();
            } catch (InterruptedException ex) {
                Exceptions.printStackTrace(ex);
            }
            assertNotNull(lastException);
            assertEquals(ec, lastException.getClass());
        }
    }
    CheckingCallback cb = new CheckingCallback();
    new Intent("NONE", new URI("broken://resource")).execute(cb);
    cb.checkLastFailure(RuntimeException.class);
    new Intent("NONE", new URI("brokensb://resource")).execute(cb);
    cb.checkLastFailure(RuntimeException.class);
    new Intent("NONE", new URI("unsupported://resource")).execute(cb);
    cb.checkLastFailure(NoAvailableHandlerException.class);
    new Intent("TEST", new URI("unsupported://resource")).execute(cb);
    cb.checkLastResult(HANDLED_BY_TEST);
    new Intent(Intent.ACTION_VIEW, new URI("netbeans://resource")).execute(cb);
    cb.checkLastResult(HANDLED_BY_NB);
    new Intent(Intent.ACTION_VIEW, new URI("netbeans://resource?someParam=x")).execute(cb);
    cb.checkLastResult(HANDLED_BY_NB);
    new Intent(Intent.ACTION_VIEW, new URI("netbeans://resource?x=y&requiredParam=123")).execute(cb);
    cb.checkLastResult(HANDLED_BY_NB_PARAM);
    new Intent(Intent.ACTION_VIEW, new URI("setback://resource")).execute(cb);
    cb.checkLastResult(HANDLED_BY_SETBACK);
}

