    } catch (IllegalStateException ex) {
    } catch (IndexOutOfBoundsException ex) {
    }
    try {
        model.removeElementAt(4);
        fail("an exception should be thrown");
    } catch (IllegalStateException ex) {
    } catch (IndexOutOfBoundsException ex) {
    }
    try {
        model.removeElementAt(5);
        fail("an exception should be thrown");
    } catch (IllegalStateException ex) {
    } catch (IndexOutOfBoundsException ex) {
    }
}

