@Test
public void testSimple() throws Exception {
    Document doc = document();
    HighlightsList hList = highlightsListSimple(doc);
    // Fetch first
    AttributeSet attrs = hList.cutSameFont(defaultFont, 10, 10, null);
    assert (attrs instanceof CompoundAttributes) : "Non-CompoundAttributes attrs=" + attrs;
    CompoundAttributes cAttrs = (CompoundAttributes) attrs;
    assert (cAttrs.startOffset() == 0) : "startOffset=" + cAttrs.startOffset();
    HighlightItem[] items = cAttrs.highlightItems();
    assert (items.length == 3);
    assertItem(items[0], 2, null);
    assertItem(items[1], 4, attrSets[0]);
    assertItem(items[2], 6, null);
    // Fetch next
    assert (hList.startOffset() == 6);
    attrs = hList.cutSameFont(defaultFont, 10, 10, null);
    assert !(attrs instanceof CompoundAttributes);
    assert attrs == attrSets[1];
    assert (hList.startOffset() == 8);
    attrs = hList.cutSameFont(defaultFont, 10, 10, null);
    assert !(attrs instanceof CompoundAttributes);
    assert (attrs == null);
    assert (hList.startOffset() == 10);
    hList = highlightsListSimple(doc);
    attrs = hList.cutSameFont(defaultFont, 2, 2, null);
    assert !(attrs instanceof CompoundAttributes);
    assert (attrs == null);
    attrs = hList.cutSameFont(defaultFont, 10, 10, null);
    assert (hList.startOffset() == 6);
    assert (attrs instanceof CompoundAttributes) : "Non-CompoundAttributes attrs=" + attrs;
    cAttrs = (CompoundAttributes) attrs;
    assert (cAttrs.startOffset() == 2) : "startOffset=" + cAttrs.startOffset();
    items = cAttrs.highlightItems();
    assert (items.length == 2);
    assertItem(items[0], 4, attrSets[0]);
    assertItem(items[1], 6, null);
    hList = highlightsListSimple(doc);
    attrs = hList.cutSameFont(defaultFont, 3, 3, null);
    cAttrs = (CompoundAttributes) attrs;
    assert (cAttrs.startOffset() == 0) : "startOffset=" + cAttrs.startOffset();
    items = cAttrs.highlightItems();
    assert (items.length == 2);
    assertItem(items[0], 2, null);
    assertItem(items[1], 3, attrSets[0]);
    // Next
    attrs = hList.cutSameFont(defaultFont, 5, 5, null);
    cAttrs = (CompoundAttributes) attrs;
    assert (cAttrs.startOffset() == 3) : "startOffset=" + cAttrs.startOffset();
    items = cAttrs.highlightItems();
    assert (items.length == 2);
    assertItem(items[0], 4, attrSets[0]);
    assertItem(items[1], 5, null);
    // Next
    attrs = hList.cutSameFont(defaultFont, 7, 7, null);
    assert !(attrs instanceof CompoundAttributes);
    assert (attrs == null);
    assert (hList.startOffset() == 6);
    // Next
    attrs = hList.cutSameFont(defaultFont, 7, 7, null);
    assert !(attrs instanceof CompoundAttributes);
    assert (attrs == attrSets[1]);
    assert (hList.startOffset() == 7);
    // Next
    attrs = hList.cutSameFont(defaultFont, 10, 10, null);
    assert !(attrs instanceof CompoundAttributes);
    assert (attrs == attrSets[1]);
    assert (hList.startOffset() == 8);
    // Next
    attrs = hList.cutSameFont(defaultFont, 10, 10, null);
    assert !(attrs instanceof CompoundAttributes);
    assert (attrs == null);
    assert (hList.startOffset() == 10);
}

@Test
public void testSimple() throws Exception {
    HighlightItem[] phItems = new HighlightItem[] { // <2,4> [0]
    new HighlightItem(4, attrSets[0]), // <4,8> [1]
    new HighlightItem(8, attrSets[1]), // <8,12> [0]
    new HighlightItem(12, attrSets[0]), // <12,14> [1]
    new HighlightItem(14, attrSets[1]), // <14,16> null
    new HighlightItem(16, null), // <16,18> [0]
    new HighlightItem(18, attrSets[0]), // <18,20> [2]
    new HighlightItem(20, attrSets[2]) };
    HighlightsList phList = new HighlightsList(2, phItems);
    ViewPaintHighlights vph = new ViewPaintHighlights(phList);
    AttributeSet attrSets31 = AttributesUtilities.createComposite(attrSets[1], attrSets[3]);
    AttributeSet attrSets30 = AttributesUtilities.createComposite(attrSets[0], attrSets[3]);
    AttributeSet attrSets02 = AttributesUtilities.createComposite(attrSets[2], attrSets[0]);
    HighlightItem[] vhItems = new HighlightItem[] { // <11,13> null
    new HighlightItem(13, null), // <13,15> [3]
    new HighlightItem(15, attrSets[3]), // <15,17> [0]
    new HighlightItem(17, attrSets[0]) };
    CompoundAttributes cvAttrs = new CompoundAttributes(11, vhItems);
    // length ignored
    TestHighlightsView testView = new TestHighlightsView(11, 6, cvAttrs);
    vph.reset(testView, 0);
    assertHighlightsSequence(vph, 11, 12, attrSets[0], 13, attrSets[1], 14, attrSets31, 15, attrSets[3], 16, attrSets[0], 17, attrSets[0]);
    vph.reset(testView, 0);
    assertHighlightsSequence(vph, 11, 12, attrSets[0], 13, attrSets[1], 14, attrSets31, 15, attrSets[3], 16, attrSets[0], 17, attrSets[0]);
    // have shift 2 chars
    vph.reset(testView, 2);
    assertHighlightsSequence(vph, 13, 14, attrSets31, 15, attrSets[3], 16, attrSets[0], 17, attrSets[0]);
    // Simulate the view move forward by 2 chars
    testView.setStartOffset(13);
    // View highlights are as follows:
    // <13,15> null         <10,12> [0]
    // <15,17> [3]          <12,14> [1]
    // <17,19> [0]          <14,16> null
    //                      <16,18> [0]
    //                      <18,20> [2]
    vph.reset(testView, 0);
    assertHighlightsSequence(vph, 13, 14, attrSets[1], 15, null, 16, attrSets[3], 17, attrSets30, 18, attrSets[0], 19, attrSets02);
    vph.reset(testView, 1);
    assertHighlightsSequence(vph, 14, 15, null, 16, attrSets[3], 17, attrSets30, 18, attrSets[0], 19, attrSets02);
    // Simulate the view moves back by 1 char
    testView.setStartOffset(10);
    // View highlights are as follows:
    // <10,12> null         <10,12> [0]
    // <12,14> [3]          <12,14> [1]
    // <14,16> [0]          <14,16> null
    //                      <16,18> [0]
    //                      <18,20> [2]
    vph.reset(testView, 0);
    assertHighlightsSequence(vph, 10, 12, attrSets[0], 14, attrSets31, 16, attrSets[0]);
    // Simulate the view moves back by 7 chars
    testView.setStartOffset(4);
    // View highlights are as follows:
    // <4,6> null           <2,4> [0]
    // <6,8> [3]            <4,8> [1]
    // <8,10> [0]           <8,12> [0]
    //                      <12,14> [1]
    //                      <14,16> null
    //                      <16,18> [0]
    //                      <18,20> [2]
    vph.reset(testView, 0);
    assertHighlightsSequence(vph, 4, 6, attrSets[1], 8, attrSets31, 10, attrSets[0]);
    // Shift 3
    vph.reset(testView, 3);
    assertHighlightsSequence(vph, 7, 8, attrSets31, 10, attrSets[0]);
    // Regular attributes
    testView.setAttributes(attrSets[3]);
    testView.setStartOffset(6);
    vph.reset(testView, 0);
    assertHighlightsSequence(vph, 6, 8, attrSets31, 12, attrSets30);
    vph.reset(testView, 2);
    assertHighlightsSequence(vph, 8, 12, attrSets30);
    // Regular attributes
    testView.setAttributes(null);
    testView.setStartOffset(6);
    vph.reset(testView, 0);
    assertHighlightsSequence(vph, 6, 8, attrSets[1], 12, attrSets[0]);
}

