@Test
public void testBasicEscaping() {
    String text = "";
    String escapedText = "";
    checkEscapeAndUnEscape(text, escapedText);
    text = "test";
    escapedText = "test";
    checkEscapeAndUnEscape(text, escapedText);
    text = "a < b && c > d";
    escapedText = "a &lt; b &amp;&amp; c &gt; d";
    checkEscapeAndUnEscape(text, escapedText);
    text = "\" test \"";
    escapedText = "&quot; test &quot;";
    checkEscapeAndUnEscape(text, escapedText);
    text = " &";
    escapedText = " &amp;";
    checkEscapeAndUnEscape(text, escapedText);
}

