@Test
public void testCollector() throws Exception {
    File testFile = new File(work, "Test.java");
    final String origin = "/** (COMM1) This comment belongs before class */\n" + "public class Clazz {\n" + "\n\n\n//TODO: (COMM2) This is just right under class (inside)" + "\n\n\n\n\n\n" + "/** (COMM3) This belongs to encapsulate field */\n" + "public int field = 9;\n\n //TODO: (COMM4) This is inside the class comment\n" + "/** (COMM5) method which do something */\n" + "public void method() {\n" + "\t//TODO: (COMM6) Implement this method to do something \n" + "}\n" + "private String str = \"string object\" //(COMM7) NOI18N\n" + "}\n";
    TestUtilities.copyStringToFile(testFile, origin);
    JavaSource src = getJavaSource(testFile);
    Task<WorkingCopy> task = new Task<WorkingCopy>() {

        protected CommentHandlerService service;

        public void run(WorkingCopy workingCopy) throws Exception {
            //                CommentCollector cc = CommentCollector.getInstance();
            workingCopy.toPhase(JavaSource.Phase.PARSED);
            //                cc.collect(workingCopy);
            CompilationUnitTree cu = workingCopy.getCompilationUnit();
            GeneratorUtilities.get(workingCopy).importComments(cu, cu);
            service = CommentHandlerService.instance(workingCopy.impl.getJavacTask().getContext());
            CommentPrinter printer = new CommentPrinter(service);
            cu.accept(printer, null);
            TreeVisitor<Void, Void> w = new TreeScanner<Void, Void>() {

                @Override
                public Void visitClass(ClassTree node, Void aVoid) {
                    verify(node, CommentSet.RelativePosition.PRECEDING, service, "/** (COMM1) This comment belongs before class */");
                    return super.visitClass(node, aVoid);
                }

                @Override
                public Void visitVariable(VariableTree node, Void aVoid) {
                    if (node.toString().contains("field")) {
                        verify(node, CommentSet.RelativePosition.PRECEDING, service, "//TODO: (COMM2) This is just right under class (inside)", "/** (COMM3) This belongs to encapsulate field */");
                    }
                    return super.visitVariable(node, aVoid);
                }

                @Override
                public Void visitLiteral(LiteralTree node, Void aVoid) {
                    if (node.toString().contains("string")) {
                        verify(node, CommentSet.RelativePosition.INLINE, service, "//(COMM7) NOI18N");
                    }
                    return super.visitLiteral(node, aVoid);
                }

                @Override
                public Void visitMethod(MethodTree node, Void aVoid) {
                    if (node.toString().contains("method")) {
                        verify(node, CommentSet.RelativePosition.PRECEDING, service, "//TODO: (COMM4) This is inside the class comment", "/** (COMM5) method which do something */");
                        verify(node.getBody(), CommentSet.RelativePosition.INNER, service, /*XXX:*/
                        "\n\t".trim(), "//TODO: (COMM6) Implement this method to do something");
                    }
                    return super.visitMethod(node, aVoid);
                }
            };
            cu.accept(w, null);
        }
    };
    src.runModificationTask(task);
}

