    assertEquals("/a/b/", trimDupliciteInitialSlashes("/a/b/"));
    assertEquals("/", trimDupliciteInitialSlashes("//"));
    assertEquals("/a", trimDupliciteInitialSlashes("//a"));
    assertEquals("/ab", trimDupliciteInitialSlashes("//ab"));
    assertEquals("/ab/", trimDupliciteInitialSlashes("//ab/"));
    assertEquals("/a//", trimDupliciteInitialSlashes("//a//"));
    assertEquals("/ab//", trimDupliciteInitialSlashes("//ab//"));
    assertEquals("/a/b", trimDupliciteInitialSlashes("//a/b"));
