    GlobalComplexType gct = (GlobalComplexType) ncr.get();
    long after = System.currentTimeMillis();
    long delay = after - before;
    assertTrue("Delay=" + delay, delay < 100L);
    System.out.println("Delay1=" + delay);
    //
    assertNotNull(gct);
    assertEquals(gct.getName(), "C1");
    //
    // Try again. It should be much faster now.
    e1 = (GlobalElement) sm.getSchema().getChildren().get(2);
    assertNotNull(e1);
    // NOI18N
    assertEquals(e1.getName(), "A2");
    ncr = e1.getType();
    name = ncr.getQName().getNamespaceURI() + ":" + ncr.getQName().getLocalPart();
    // NOI18N
    assertEquals(name, "hl7_performance_test:C2");
    //this is when it'll try to resolve
    //
    before = System.currentTimeMillis();
    gct = (GlobalComplexType) ncr.get();
    after = System.currentTimeMillis();
    delay = after - before;
    assertTrue("Delay=" + delay, delay < 5L);
    System.out.println("Delay2=" + delay);
    //
    assertNotNull(gct);
    assertEquals(gct.getName(), "C2");
    //
    // Wait 5.5 seconds and try third time
    Thread.sleep(5500);
    //
    e1 = (GlobalElement) sm.getSchema().getChildren().get(3);
    assertNotNull(e1);
    // NOI18N
    assertEquals(e1.getName(), "A3");
    ncr = e1.getType();
    name = ncr.getQName().getNamespaceURI() + ":" + ncr.getQName().getLocalPart();
    // NOI18N
    assertEquals(name, "hl7_performance_test:C3");
    //this is when it'll try to resolve
    //
    before = System.currentTimeMillis();
    gct = (GlobalComplexType) ncr.get();
    after = System.currentTimeMillis();
    delay = after - before;
    assertTrue("Delay=" + delay, delay < 30L);
    System.out.println("Delay3=" + delay);
    //
    assertNotNull(gct);
    assertEquals(gct.getName(), "C3");
}

/**
 * Checks the index is created after reaching threshold amount of
 * global components and also the index removed if the amound goes down
 * below another threshold.
 */
@Test
public void testIndexCreationThreshold() throws Exception {
    SchemaModel sm;
    //
    // sm = Util.loadSchemaModel2("resources/performance2/B.xsd"); // NOI18N
    // NOI18N
    sm = Util.loadSchemaModel2("resources/performance2.zip", "B.xsd");
    //
    assertTrue(sm.getState() == State.VALID);
    //
    UndoManager um = new javax.swing.undo.UndoManager();
    AbstractDocumentModel.class.cast(sm).addUndoableEditListener(um);
    //
    Schema schema = sm.getSchema();
    String initialTargetNamespace = schema.getTargetNamespace();
    String targetNamspace = initialTargetNamespace;
    assertEquals(targetNamspace, "hl7_performance_test");
    //
    String newTargetNamespace = "newTargetNamespace";
    String newTargetNamespace2 = "newTargetNamespace2";
    sm.startTransaction();
    try {
        schema.setTargetNamespace(newTargetNamespace);
        //
        targetNamspace = schema.getTargetNamespace();
        assertEquals(targetNamspace, newTargetNamespace);
        //
        schema.setTargetNamespace(newTargetNamespace2);
        //
        targetNamspace = schema.getTargetNamespace();
        assertEquals(targetNamspace, newTargetNamespace2);
    } finally {
        sm.endTransaction();
    }
    //
    targetNamspace = schema.getTargetNamespace();
    assertEquals(targetNamspace, newTargetNamespace2);
    //
    um.undo();
    //
    targetNamspace = schema.getTargetNamespace();
    assertEquals(targetNamspace, initialTargetNamespace);
}

/**
 * Each schema imports a substitution group base, and defines a global
 * element that is part of this substitution group.
 * FindSubstitutionsVisitor should resolve this substitution.
 */
@Test
public void shouldResolveSubstitutionsFromLinkedSchemas() {
    GlobalElement substitutionGroupHead = getCachedElement(parentModel, SUBSTITUTION_GROUP_HEAD);
    GlobalElement expectedSubstitutionOne = getCachedElement(childModelOne, SUBSTITUTION_ELEMENT_ONE);
    GlobalElement expectedSubstitutionTwo = getCachedElement(childModelTwo, SUBSTITUTION_ELEMENT_TWO);
    Set<GlobalElement> possibleSubstitutionsOne = FindSubstitutions.resolveSubstitutions(childModelOne, substitutionGroupHead);
    Set<GlobalElement> possibleSubstitutionsTwo = FindSubstitutions.resolveSubstitutions(childModelTwo, substitutionGroupHead);
    assertEquals(1, possibleSubstitutionsOne.size());
    assertSame("invalid substitution", expectedSubstitutionOne, possibleSubstitutionsOne.iterator().next());
    assertEquals(1, possibleSubstitutionsTwo.size());
    assertSame("invalid substitution", expectedSubstitutionTwo, possibleSubstitutionsTwo.iterator().next());
}
